     1	using Microsoft.Xna.Framework;
     2	using MonsterEdit.monsters;
     3	using ProjectTower.character;
     4	using ProjectTower.gamestate;
     5	using ProjectTower.hit;
     6	using ProjectTower.map;
     7	
     8	namespace ProjectTower.particles.particles.debris;
     9	
    10	internal class FlameTrail : BaseParticle
    11	{
    12		public override void Init(Particle p, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
    13		{
    14			p.loc = loc;
    15			p.traj = traj;
    16			p.size = size;
    17			p.rotation = rotation;
    18			p.flags = Rand.GetRandomInt(5, 9);
    19			p.owner = owner;
    20			p.frame = Rand.GetRandomFloat(1f, 1.2f);
    21			p.aux = 1;
    22			base.Init(p, loc, traj, size, rotation, flags, owner);
    23		}
    24	
    25		public override void Update(Particle p, float frameTime)
    26		{
    27			Vector2 loc = p.loc;
    28			float frame = p.frame;
    29			if (p.aux == 1)
    30			{
    31				p.traj.Y += frameTime * 500f;
    32				if (CharCols.TestCol(p.loc, falling: false, 0f))
    33				{
    34					p.traj.X = (p.traj.Y = 0f);
    35					p.aux = 0;
    36				}
    37			}
    38			p.loc.Y += p.traj.Y * frameTime;
    39			if (CharCols.TestCol(p.loc, falling: false, 0f))
    40			{
    41				p.loc.Y = loc.Y;
    42				p.aux = 0;
    43			}
    44			p.loc.X += p.traj.X * frameTime;
    45			if (CharCols.TestCol(p.loc, falling: false, 0f))
    46			{
    47				p.traj.X = 0f;
    48			}
    49			p.frame -= frameTime;
    50			if (p.frame <= 0f)
    51			{
    52				p.exists = false;
    53				return;
    54			}
    55			if ((int)(p.frame * 2f) != (int)(frame * 2f))
    56			{
    57				p.traj.X *= 0.6f;
    58			}
    59			if ((int)(p.frame * 60f) != (int)(frame * 60f))
    60			{
    61				ParticleManager.AddAdditiveParticle((p.aux == 1) ? 1 : 46, p.loc + ((p.aux == 1) ? Rand.GetRandomVec2(-20f, 20f, -40f, 40f) : Rand.GetRandomVec2(-40f, 40f, 0f, 0f)), (p.aux == 1) ? Rand.GetRandomVec2((0f - p.traj.X) * 0.5f, p.traj.X, -300f, 0f) : Rand.GetRandomVec2(-10f, 100f, -300f, -100f), Rand.GetRandomFloat(0.5f, 1f) * p.size * ((p.aux == 1) ? 1.5f : 0.6f), 0f, 0, -1);
    62			}
    63			if ((int)(p.frame * 30f) == (int)(frame * 30f))
    64			{
    65				return;
    66			}
    67			ParticleManager.AddBackSubtractiveParticle(0, p.loc + Rand.GetRandomVec2(-40f, 40f, -30f, 0f), Rand.GetRandomVec2(-10f, 50f, -300f, -100f), p.size * Rand.GetRandomFloat(0f, 1f), 0f, -1, -1);
    68			for (int i = 0; i < CharMgr.character.Length; i++)
    69			{
    70				Character character = CharMgr.character[i];
    71				if (!character.exists)
    72				{
    73					continue;
    74				}
    75				int type = MonsterCatalog.catalog[character.monsterIdx].type;
    76				if ((uint)(type - 2) <= 4u)
    77				{
    78					continue;
    79				}
    80				bool flag = false;
    81				if (p.owner > -1)
    82				{
    83					Character owner = CharMgr.character[p.owner];
    84					flag = HitTeam.GetSameTeam(character, owner);
    85				}
    86				if (flag)
    87				{
    88					continue;
    89				}
    90				Vector2 vector = character.loc - p.loc;
    91				if (vector.X > -100f && vector.X < 100f && vector.Y > -100f && vector.Y < 100f && HitPoint.CheckPoint(p.loc, character, 0f) && (!character.boss || MapMgr.map.triggerMgr.GetActiveArenaIdx(character) <= -1 || GameStateManager.GetMainPlayer().camMgr.latestArenaIdx > -1))
    92				{
    93					float damage = 1f;
    94					if (p.owner > -1 && CharMgr.character[p.owner].stats.GetRingFlag(44) && p.owner != character.ID)
    95					{
    96						damage = 1.5f;
    97					}
    98					character.buffs.SetBuff(1, character.stats.GetAdjustedDamage(damage, 2));
    99					if (!character.aggrod)
   100					{
   101						character.Aggro(aggrodByFriend: false);
   102					}
   103				}
   104			}
   105		}
   106	
   107		public override void Draw(Particle p, float brite)
   108		{
   109			base.Draw(p, brite);
   110		}
   111	}
